#define MAXN 255
#define INF 1000000000

int grid[MAXN][MAXN];
int st[MAXN][MAXN][9][9]; // sparse table for 2D RMQ
int log2[MAXN];

void build_log2(int n) {
    log2[1] = 0;
    for (int i = 2; i <= n; i++)
        log2[i] = log2[i/2] + 1;
}

int min(int a, int b) {
    return a < b ? a : b;
}

void build_sparse_table(int n, int m) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            st[i][j][0][0] = grid[i][j];

    for (int ki = 0; (1 << ki) <= n; ki++) {
        for (int kj = 0; (1 << kj) <= m; kj++) {
            if (ki == 0 && kj == 0) continue;
            for (int i = 0; i + (1 << ki) <= n; i++) {
                for (int j = 0; j + (1 << kj) <= m; j++) {
                    if (ki == 0) {
                        st[i][j][ki][kj] = min(
                            st[i][j][ki][kj-1],
                            st[i][j + (1 << (kj-1))][ki][kj-1]
                        );
                    } else {
                        st[i][j][ki][kj] = min(
                            st[i][j][ki-1][kj],
                            st[i + (1 << (ki-1))][j][ki-1][kj]
                        );
                    }
                }
            }
        }
    }
}

int query(int r1, int c1, int r2, int c2) {
    int ki = log2[r2 - r1 + 1];
    int kj = log2[c2 - c1 + 1];

    int min1 = min(st[r1][c1][ki][kj], 
                   st[r1][c2 - (1 << kj) + 1][ki][kj]);
    int min2 = min(st[r2 - (1 << ki) + 1][c1][ki][kj],
                   st[r2 - (1 << ki) + 1][c2 - (1 << kj) + 1][ki][kj]);
    return min(min1, min2);
}

