static int min_int(int a, int b) { return a < b ? a : b; }

int main(void) {
    int N, M;

    while (scanf("%d %d", &N, &M) == 2) {
        int total = N * M;
        int *a = (int *)malloc((size_t)total * sizeof(int));
        if (!a) return 0;

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < M; ++j) {
                scanf("%d", &a[i * M + j]);
            }
        }

        int maxNM = (N > M ? N : M) + 1;
        int *lg = (int *)malloc((size_t)maxNM * sizeof(int));
        if (!lg) {
            free(a);
            return 0;
        }
        lg[0] = -1;
        for (int i = 1; i < maxNM; ++i) lg[i] = lg[i >> 1] + 1;

        int K1 = lg[N] + 1;
        int K2 = lg[M] + 1;

        int **st = (int **)malloc((size_t)K1 * sizeof(int *));
        if (!st) {
            free(a);
            free(lg);
            return 0;
        }

        for (int k1 = 0; k1 < K1; ++k1) {
            st[k1] = (int *)malloc((size_t)K2 * N * M * sizeof(int));
            if (!st[k1]) {
                for (int t = 0; t < k1; ++t) free(st[t]);
                free(st);
                free(a);
                free(lg);
                return 0;
            }
        }

        #define ST(k1,k2,i,j) st[(k1)][ ((k2) * N + (i)) * M + (j) ]

        for (int i = 0; i < N; ++i)
            for (int j = 0; j < M; ++j)
                ST(0, 0, i, j) = a[i * M + j];

        for (int k2 = 1; k2 < K2; ++k2) {
            int len = 1 << (k2 - 1);
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j + (1 << k2) <= M; ++j) {
                    ST(0, k2, i, j) = min_int(ST(0, k2 - 1, i, j),
                                              ST(0, k2 - 1, i, j + len));
                }
            }
        }

        for (int k1 = 1; k1 < K1; ++k1) {
            int len1 = 1 << (k1 - 1);
            for (int k2 = 0; k2 < K2; ++k2) {
                for (int i = 0; i + (1 << k1) <= N; ++i) {
                    int maxj = M - (1 << k2) + 1;
                    for (int j = 0; j < maxj; ++j) {
                        ST(k1, k2, i, j) = min_int(ST(k1 - 1, k2, i, j),
                                                   ST(k1 - 1, k2, i + len1, j));
                    }
                }
            }
        }

        int Q;
        scanf("%d", &Q);
        while (Q--) {
            int x1, y1, x2, y2;
            scanf("%d %d %d %d", &x1, &y1, &x2, &y2);

            /* assume 1-based inclusive coordinates */
            x1--; y1--; x2--; y2--;

            if (x1 > x2) { int t = x1; x1 = x2; x2 = t; }
            if (y1 > y2) { int t = y1; y1 = y2; y2 = t; }

            int h = x2 - x1 + 1;
            int w = y2 - y1 + 1;
            int k1 = lg[h];
            int k2 = lg[w];
            int i2 = x2 - (1 << k1) + 1;
            int j2 = y2 - (1 << k2) + 1;

            int ans = ST(k1, k2, x1, y1);
            ans = min_int(ans, ST(k1, k2, i2, y1));
            ans = min_int(ans, ST(k1, k2, x1, j2));
            ans = min_int(ans, ST(k1, k2, i2, j2));

            printf("%d\n", ans);
        }

        for (int k1 = 0; k1 < K1; ++k1) free(st[k1]);
        free(st);
        free(a);
        free(lg);
    }

    return 0;
}

