def solve():
    while True:
        line = input()
        if not line:
            break
        n, m = map(int, line.split())
        if n == 0 and m == 0:
            break

        grid = []
        for _ in range(n):
            grid.append(list(map(int, input().split())))

        # Build 2D sparse table for RMQ
        logn = [0] * (n + 1)
        logm = [0] * (m + 1)
        for i in range(2, n + 1):
            logn[i] = logn[i // 2] + 1
        for i in range(2, m + 1):
            logm[i] = logm[i // 2] + 1

        K = logn[n] + 1
        L = logm[m] + 1

        st = [[[[0] * L for _ in range(K)] for _ in range(m)] for _ in range(n)]
        # Actually we need: st[k][l][i][j] = min over subgrid of size 2^k x 2^l starting at (i,j)
        # Better: st[i][j][k][l] but that's large; let's use st[k][l][i][j] approach with 4D list carefully.

        # Let's do it more memory-efficient:
        # st[k][i][j] = min over 2^k rows starting at i, for each column j
        st_row = [[[0] * m for _ in range(n)] for _ in range(K)]
        for i in range(n):
            for j in range(m):
                st_row[0][i][j] = grid[i][j]
        for k in range(1, K):
            step = 1 << (k-1)
            for i in range(n - (1<<k) + 1):
                for j in range(m):
                    st_row[k][i][j] = min(st_row[k-1][i][j], st_row[k-1][i+step][j])

        # Now st_col[k][l][i][j] = min over 2^k rows and 2^l columns
        st = [[[[0] * m for _ in range(n)] for _ in range(L)] for _ in range(K)]
        for k in range(K):
            for i in range(n - (1<<k) + 1):
                # initialize l=0
                for j in range(m):
                    st[k][0][i][j] = st_row[k][i][j]
                for l in range(1, L):
                    stepc = 1 << (l-1)
                    for j in range(m - (1<<l) + 1):
                        st[k][l][i][j] = min(st[k][l-1][i][j], st[k][l-1][i][j+stepc])

        q = int(input())
        for _ in range(q):
            x1, y1, x2, y2 = map(int, input().split())
            x1 -= 1; y1 -= 1; x2 -= 1; y2 -= 1
            k = logn[x2 - x1 + 1]
            l = logm[y2 - y1 + 1]
            h = 1 << k
