    while (true) {
        int n, m;
        if (!(cin >> n >> m)) return 0;
        if (n == 0 && m == 0) break;

        vector<vector<int>> a(n, vector<int>(m));
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                cin >> a[i][j];

        int q;
        cin >> q;

        // Build 2D sparse table for range minimum query
        int logN = 0, logM = 0;
        while ((1 << logN) <= n) ++logN;
        while ((1 << logM) <= m) ++logM;

        vector<int> lgN(n + 1), lgM(m + 1);
        lgN[1] = 0;
        for (int i = 2; i <= n; ++i) lgN[i] = lgN[i / 2] + 1;
        lgM[1] = 0;
        for (int i = 2; i <= m; ++i) lgM[i] = lgM[i / 2] + 1;

        // st[kx][ky][i][j] = minimum on rectangle
        // [i, i+2^kx-1] x [j, j+2^ky-1]
        vector<vector<vector<vector<int>>>> st(
            logN, vector<vector<vector<int>>>(
                      logM, vector<vector<int>>(n, vector<int>(m))));

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                st[0][0][i][j] = a[i][j];

        for (int ky = 1; ky < logM; ++ky) {
            int len = 1 << (ky - 1);
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j + (1 << ky) <= m; ++j) {
                    st[0][ky][i][j] = min(st[0][ky - 1][i][j],
                                          st[0][ky - 1][i][j + len]);
                }
            }
        }

        for (int kx = 1; kx < logN; ++kx) {
            int lenx = 1 << (kx - 1);
            for (int ky = 0; ky < logM; ++ky) {
                for (int i = 0; i + (1 << kx) <= n; ++i) {
                    for (int j = 0; j + (1 << ky) <= m; ++j) {
                        st[kx][ky][i][j] = min(st[kx - 1][ky][i][j],
                                               st[kx - 1][ky][i + lenx][j]);
                    }
                }
            }
        }

        auto query = [&](int x1, int y1, int x2, int y2) -> int {
            int h = x2 - x1 + 1;
            int w = y2 - y1 + 1;
            int kx = lgN[h];
            int ky = lgM[w];
            int nx = x2 - (1 << kx) + 1;
            int ny = y2 - (1 << ky) + 1;

            int v1 = min(st[kx][ky][x1][y1], st[kx][ky][x1][ny]);
            int v2 = min(st[kx][ky][nx][y1], st[kx][ky][nx][ny]);
            return min(v1, v2);
        };

        while (q--) {
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            --x1; --y1; --x2; --y2;
            if (x1 > x2) swap(x1, x2);
            if (y1 > y2) swap(y1, y2);
            cout << query(x1, y1, x2, y2) << '\n';
        }
    }

    return 0;
}

