                }
            }

            // Build 2D sparse table
            int logR = (int)(Math.log(R) / Math.log(2)) + 1;
            int logC = (int)(Math.log(C) / Math.log(2)) + 1;
            int[][][][] st = new int[logR][R][logC][C];

            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    st[0][i][0][j] = grid[i][j];
                }
                for (int kj = 1; kj < logC; kj++) {
                    for (int j = 0; j + (1 << kj) <= C; j++) {
                        st[0][i][kj][j] = Math.min(st[0][i][kj-1][j], st[0][i][kj-1][j + (1 << (kj-1))]);
                    }
                }
            }

            for (int ki = 1; ki < logR; ki++) {
                for (int i = 0; i + (1 << ki) <= R; i++) {
                    for (int kj = 0; kj < logC; kj++) {
                        for (int j = 0; j + (1 << kj) <= C; j++) {
                            st[ki][i][kj][j] = Math.min(st[ki-1][i][kj][j], st[ki-1][i + (1 << (ki-1))][kj][j]);
                        }
                    }
                }
            }

            int Q = Integer.parseInt(br.readLine().trim());
            for (int q = 0; q < Q; q++) {
                StringTokenizer stok = new StringTokenizer(br.readLine());
                int r1 = Integer.parseInt(stok.nextToken()) - 1;
                int c1 = Integer.parseInt(stok.nextToken()) - 1;
                int r2 = Integer.parseInt(stok.nextToken()) - 1;
                int c2 = Integer.parseInt(stok.nextToken()) - 1;

                int ki = (int)(Math.log(r2 - r1 + 1) / Math.log(2));
                int kj = (int)(Math.log(c2 - c1 + 1) / Math.log(2));

                int min1 = Math.min(st[ki][r1][kj][c1], st[ki][r1][kj][c2 - (1 << kj) + 1]);
                int min2 = Math.min(st[ki][r2 - (1 << ki) + 1][kj][c1], st[ki][r2 - (1 << ki) + 1][kj][c2 - (1 << kj) + 1]);
                int result = Math.min(min1, min2);
                sb.append(result).append("\n");
            }
        }
        System.out.print(sb);
    }
}

