                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < W; j++) {
                    grid[i][j] = Integer.parseInt(st.nextToken());
                }
            }

            // Build 2D sparse table
            int LOG = 1;
            while ((1 << LOG) <= Math.max(H, W)) LOG++;

            // sparse[k1][k2][i][j] = min in rect [i, i+2^k1) x [j, j+2^k2)
            int[][][][] sparse = new int[LOG][LOG][H][W];

            // Initialize k1=0, k2=0
            for (int i = 0; i < H; i++)
                for (int j = 0; j < W; j++)
                    sparse[0][0][i][j] = grid[i][j];

            // Fill k2 for k1=0
            for (int k2 = 1; k2 < LOG; k2++)
                for (int i = 0; i < H; i++)
                    for (int j = 0; j + (1 << k2) <= W; j++)
                        sparse[0][k2][i][j] = Math.min(sparse[0][k2-1][i][j], sparse[0][k2-1][i][j + (1 << (k2-1))]);

            // Fill k1
            for (int k1 = 1; k1 < LOG; k1++)
                for (int k2 = 0; k2 < LOG; k2++)
                    for (int i = 0; i + (1 << k1) <= H; i++)
                        for (int j = 0; j < W; j++)
                            if (k2 == 0 || j + (1 << k2) <= W)
                                sparse[k1][k2][i][j] = Math.min(sparse[k1-1][k2][i][j], sparse[k1-1][k2][i + (1 << (k1-1))][j]);

            int Q = Integer.parseInt(br.readLine().trim());
            for (int q = 0; q < Q; q++) {
                st = new StringTokenizer(br.readLine());
                int r1 = Integer.parseInt(st.nextToken()) - 1;
                int c1 = Integer.parseInt(st.nextToken()) - 1;
                int r2 = Integer.parseInt(st.nextToken()) - 1;
                int c2 = Integer.parseInt(st.nextToken()) - 1;

                int k1 = 31 - Integer.numberOfLeadingZeros(r2 - r1 + 1);
                int k2 = 31 - Integer.numberOfLeadingZeros(c2 - c1 + 1);

                int ans = Math.min(
                    Math.min(sparse[k1][k2][r1][c1], sparse[k1][k2][r2-(1<<k1)+1][c1]),
                    Math.min(sparse[k1][k2][r1][c2-(1<<k2)+1], sparse[k1][k2][r2-(1<<k1)+1][c2-(1<<k2)+1])
                );
                sb.append(ans).append('\n');
            }
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // 2D Sparse Table for Range Minimum Query
    static class SparseTable2D {
        int n, m;
        int[] log2;
        int[][][][] st; // st[kx][ky][i][j] = min in rectangle (i..i+2^kx-1, j..j+2^ky-1)

        SparseTable2D(int[][] a) {
            n = a.length;
            m = a[0].length;

            int maxDim = Math.max(n, m);
            log2 = new int[maxDim + 1];
            for (int i = 2; i <= maxDim; i++) log2[i] = log2[i >> 1] + 1;

            int Kx = log2[n] + 1;
            int Ky = log2[m] + 1;

            st = new int[Kx][Ky][][];

            // ky = 0
            st[0][0] = new int[n][m];
            for (int i = 0; i < n; i++) {
                System.arraycopy(a[i], 0, st[0][0][i], 0, m);
            }

            // Build along columns for kx = 0
            for (int ky = 1; ky < Ky; ky++) {
                int len = 1 << (ky - 1);
                st[0][ky] = new int[n][m - (1 << ky) + 1];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j + (1 << ky) <= m; j++) {
                        st[0][ky][i][j] = Math.min(st[0][ky - 1][i][j], st[0][ky - 1][i][j + len]);
                    }
                }
            }

            // Build along rows
            for (int kx = 1; kx < Kx; kx++) {
                int len = 1 << (kx - 1);
                for (int ky = 0; ky < Ky; ky++) {
                    int rows = n - (1 << kx) + 1;
                    int cols = m - (1 << ky) + 1;
                    st[kx][ky] = new int[rows][cols];
                    for (int i = 0; i + (1 << kx) <= n; i++) {
                        for (int j = 0; j + (1 << ky) <= m; j++) {
                            st[kx][ky][i][j] = Math.min(st[kx - 1][ky][i][j], st[kx - 1][ky][i + len][j]);
                        }
                    }
                }
            }
        }

        int query(int x1, int y1, int x2, int y2) {
            // inclusive coordinates, 0-based
            int kx = log2[x2 - x1 + 1];
            int ky = log2[y2 - y1 + 1];
            int rx = x2 - (1 << kx) + 1;
            int ry = y2 - (1 << ky) + 1;

            int a = st[kx][ky][x1][y1];
            int b = st[kx][ky][rx][y1];
            int c = st[kx][ky][x1][ry];
            int d = st[kx][ky][rx][ry];

            return Math.min(Math.min(a, b), Math.min(c, d));
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int datasets;
        try {
            datasets = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        for (int tc = 0; tc < datasets; tc++) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = fs.nextInt();
                }
            }

            SparseTable2D st = new SparseTable2D(grid);

            int q = fs.nextInt();
            while (q-- > 0) {
                int x1 = fs.nextInt() - 1;
                int y1 = fs.nextInt() - 1;
                int x2 = fs.nextInt() - 1;
                int y2 = fs.nextInt() - 1;

                if (x1 > x2) {
                    int t = x1; x1 = x2; x2 = t;
                }
                if (y1 > y2) {
                    int t = y1; y1 = y2; y2 = t;
                }

                out.append(st.query(x1, y1, x2, y2)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}
